def countOfNodes(graph, n):
    def bfs(start):
        queue = [start]
        distance = [-1] * n
        distance[start] = 0
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if distance[neighbor] == -1:
                    distance[neighbor] = distance[node] + 1
                    queue.append(neighbor)
        return distance

    even_count = 0
    for i in range(n):
        distances = bfs(i)
        even_count += sum(1 for d in distances if d != -1 and d % 2 == 0)

    # Each pair is counted twice, so divide by 2
    return even_count // 2
